// bbx web_fetch 假站点：node site.mjs <root> <port> <gatewayPort>
// 由 UserPromptSubmit hook 调起：已有实例在听就直接退出；否则脱离起一个常驻子进程，等它开始监听再退出（hook 不输出任何东西）。
// 子进程按 <root>/site/routes.json 应答 HTTPS（证书是仓库里的一次性测试 CA 叶子，见 <root>/site/tls.json），
// 每个请求记一行到 <root>/home/sitelog/requests.jsonl（方法、路径、头），落盘照常比较。
// 根目录被清掉（下一侧开跑）或 gateway 端口不再接受连接时自行退出；最长活 180 秒。
import fs from 'node:fs';
import net from 'node:net';
import https from 'node:https';
import { spawn } from 'node:child_process';

const [root, portText, gatewayText, mode] = process.argv.slice(2);
const port = Number(portText);
const gatewayPort = Number(gatewayText);
const probe = (p) => new Promise((resolve) => {
  const s = net.connect({ host: '127.0.0.1', port: p });
  s.once('connect', () => { s.destroy(); resolve(true); });
  s.once('error', () => resolve(false));
});
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

if (mode !== 'serve') {
  process.stdin.resume();
  process.stdin.on('data', () => {});
  if (!(await probe(port))) {
    spawn(process.execPath, [process.argv[1], root, portText, gatewayText, 'serve'], { detached: true, stdio: 'ignore' }).unref();
    for (let i = 0; i < 200 && !(await probe(port)); i++) await sleep(25);
  }
  process.exit(0);
}

const marker = `${root}/site/routes.json`;
const routes = JSON.parse(fs.readFileSync(marker, 'utf8'));
const tls = JSON.parse(fs.readFileSync(`${root}/site/tls.json`, 'utf8'));
const logDir = `${root}/home/sitelog`;
const server = https.createServer({ cert: tls.cert, key: tls.key }, async (req, res) => {
  for await (const _ of req) { /* drain */ }
  fs.mkdirSync(logDir, { recursive: true });
  fs.appendFileSync(`${logDir}/requests.jsonl`, JSON.stringify({ method: req.method, url: req.url, headers: req.headers }) + '\n');
  const route = routes[req.url] ?? { status: 404, body: 'no route' };
  if (route.delayMs) await sleep(route.delayMs);
  let body;
  if (route.b64 !== undefined) body = Buffer.from(route.b64, 'base64');
  else if (route.repeat) body = Buffer.concat([Buffer.from(route.repeat.prefix ?? ''), Buffer.from(route.repeat.text.repeat(route.repeat.times)), Buffer.from(route.repeat.suffix ?? '')]);
  else body = Buffer.from(route.body ?? '');
  const headers = { ...(route.headers ?? {}) };
  if (!route.chunked && !route.hang) headers['content-length'] = String(body.length);
  res.writeHead(route.status ?? 200, route.statusText ?? undefined, headers);
  if (route.hang) { res.write(body.subarray(0, route.hang)); setTimeout(() => res.destroy(), route.hangMs ?? 20000).unref(); return; }
  res.end(body);
});
server.on('tlsClientError', () => {});
for (let i = 0; ; i++) {
  try {
    await new Promise((resolve, reject) => { server.once('error', reject); server.listen(port, '127.0.0.1', resolve); });
    break;
  } catch (error) {
    if (error.code !== 'EADDRINUSE' || i > 120) process.exit(1);
    await sleep(50);
  }
}
const started = Date.now();
setInterval(async () => {
  if (!fs.existsSync(marker) || Date.now() - started > 180000 || !(await probe(gatewayPort))) process.exit(0);
}, 200);
